  getLoginProviderOptions(authType) {
    const authStorage = this.session.modelRegistry.authStorage;
    const oauthProviders = authStorage.getOAuthProviders();
    const oauthProviderIds = new Set(oauthProviders.map((provider) => provider.id));
    const options5 = oauthProviders.map((provider) => ({
      id: provider.id,
      name: provider.name,
      authType: "oauth"
    }));
    const modelProviders = new Set(this.session.modelRegistry.getAll().map((model) => model.provider));
    for (const providerId of modelProviders) {
      if (!isApiKeyLoginProvider(providerId, oauthProviderIds)) {
        continue;
      }
      options5.push({
        id: providerId,
        name: getApiKeyProviderDisplayName(providerId),
        authType: "api_key"
      });
    }
    const filteredOptions = authType ? options5.filter((option) => option.authType === authType) : options5;
    return filteredOptions.sort((a, b) => a.name.localeCompare(b.name));
  }
  getLogoutProviderOptions() {
    const authStorage = this.session.modelRegistry.authStorage;
    const oauthNameById = new Map(authStorage.getOAuthProviders().map((provider) => [provider.id, provider.name]));
    const options5 = [];
    for (const providerId of authStorage.list()) {
      const credential = authStorage.get(providerId);
      if (!credential) {
        continue;
      }
      options5.push({
        id: providerId,
        name: credential.type === "oauth" ? oauthNameById.get(providerId) ?? providerId : getApiKeyProviderDisplayName(providerId),
        authType: credential.type
      });
    }
    return options5.sort((a, b) => a.name.localeCompare(b.name));
  }
